-- == VIDEOJUEGOSZARAGOZA ====================================================
-- Migración: lecciones del perfil del cliente («Mi cuenta» → Tu perfil) y de los avisos de estado de pedidos y reparaciones.
-- Tipo:     solo inserta filas si no existen. No borra ni modifica nada.
-- ============================================================================

insert into public.aprendizajes (titulo, categoria, prioridad, regla, ejemplo_mal, ejemplo_bien)
select v.titulo, v.categoria, v.prioridad, v.regla, v.ejemplo_mal, v.ejemplo_bien
from (values
  ('Datos de perfil del cliente: solo los suyos, mínimo 14 años', 'seguridad', 1,
   'Los datos de perfil del cliente (nombre, usuario, país, provincia y fecha de nacimiento) viven en la tabla perfiles_cliente: cada cliente lee, crea y edita SOLO su fila (RLS con auth.uid()); el administrador las lee todas para el seguimiento en Administración → Usuarios y no puede editarlas; los visitantes no tocan nada y nadie borra (la fila desaparece con la cuenta). Toda tabla nueva de Supabase sale con TODOS los permisos para anon y authenticated: se retiran y se devuelven solo los necesarios (revoke … from public, anon, authenticated y grant select, insert, update to authenticated). El nombre de usuario es único sin distinguir mayúsculas y tiene formato (3-24: letras, números, punto, guion y guion bajo); la edad se calcula de la fecha de nacimiento (mínimo 14 años, que es la edad de consentimiento en España) y a Administración solo le sale la edad, no la fecha. Al guardar también se actualizan los datos de la cuenta (nombre, usuario, país), que es de donde el Foro saca el nombre. Si la tabla aún no existe la tarjeta no sale y no se rompe nada. Se prueba con pruebas/perfiles-sql.mjs (PostgreSQL local con roles y token de verdad, y la prueba de las pruebas) y pruebas/perfil-datos.mjs. Si se piden más datos personales, antes hay que actualizar la política de privacidad (la edita el dueño en Administración).',
   'Guardar el perfil en profiles (cuya actualización es solo del administrador) o dejar la tabla nueva con los permisos por defecto, que permitían borrar a cualquier cliente.', 'Una tabla propia con RLS por persona, permisos recortados, edad calculada y comprobada con roles reales en una base aislada.'),
  ('Avisos de estado de pedidos y reparaciones', 'negocio', 2,
   'Blue avisa en «Noticias y avisos» cuando la tienda cambia la etapa de un pedido o de una reparación del cliente (con sesión; las mismas etapas que ve en Perfil → Seguimientos): una fila con icono, suma al número rojo y un mensaje de Blue UNA vez que lleva a Seguimientos. Se compara con la última etapa que la persona ya vio, guardada en el móvil por cuenta; la primera vez en un dispositivo solo se apunta lo que hay (no se avisa de lo antiguo), un pedido o una reparación recién creados en su etapa inicial no son novedad, y el aviso desaparece al abrir Seguimientos. Solo se anuncian etapas reales: los textos no prometen plazos ni datos que la tienda no haya escrito. Si faltan las tablas o las columnas de seguimiento (migración sin aplicar) no hay avisos y no se rompe nada. Se prueba con pruebas/blue-panel.mjs (sesión simulada y pedidos ficticios).',
   'Avisar de todos los pedidos antiguos la primera vez que se entra, o repetir el aviso aunque la persona ya haya abierto Seguimientos.', 'Avisar solo de lo que cambió desde lo último visto y dejar de avisar al abrir Seguimientos.')
) as v(titulo, categoria, prioridad, regla, ejemplo_mal, ejemplo_bien)
where not exists (select 1 from public.aprendizajes a where a.titulo = v.titulo);
